import json, os, html, re
HERE = os.path.dirname(os.path.abspath(__file__)); K = os.path.join(HERE, '..')
CSS = re.search(r"CSS = '''(.*?)'''", open(f'{K}/lab1/build_pack.py', encoding='utf8').read(), re.S).group(1)
CSS += '.t td.r,.t th.r{text-align:right}.t.sub td{padding-top:1.1mm;padding-bottom:1.1mm}.card{border:.9pt solid var(--line);border-left:3mm solid var(--deep);border-radius:3mm;padding:3.5mm 5mm;margin:0 0 4mm}.card h3{color:var(--deep);font-size:11.5pt;margin-bottom:1mm}.card .cite{font-size:9pt;color:var(--muted);margin-bottom:2mm}.card table{width:100%;border-collapse:collapse}.card th{width:34mm;text-align:left;vertical-align:top;font-size:9.5pt;color:var(--muted);padding:1mm 2mm 1mm 0}.card td{font-size:10pt;line-height:1.4;padding:1mm 0}.rv{break-inside:avoid;margin:0 0 4.2mm}.rv h3{font-size:11pt;color:var(--deep);margin-bottom:1mm}.rv ol{margin-left:5mm}.rv li{font-size:10pt;line-height:1.42;margin-bottom:.8mm}.wk{font-size:13pt;font-weight:800;color:var(--ink);border-bottom:1.2pt solid var(--amber);padding-bottom:1mm;margin:2mm 0 3mm}'
e = html.escape
def doc(title, pages): return f'<!DOCTYPE html><html lang="el"><head><meta charset="UTF-8"><title>{e(title)}</title><link href="https://fonts.googleapis.com/css2?family=Commissioner:wght@400;500;700;800&display=swap" rel="stylesheet"><style>{CSS}</style></head><body>{"".join(pages)}</body></html>'
def page(n, N, kicker, title, body, left, right): return f'<section class="page"><header><span class="kick">{e(kicker)}</span><h1>{e(title)}</h1></header><div class="content">{body}</div><footer><span>{e(left)}</span><span>{e(right)} · σελίδα {n} από {N}</span></footer></section>'
def card(n, title, cite, rows): return f'<div class="card"><h3>Κάρτα {n} · {e(title)}</h3><p class="cite">{cite}</p><table>' + ''.join(f'<tr><th>{e(a)}</th><td>{b}</td></tr>' for a, b in rows) + '</table></div>'
line = lambda n=1: ''.join('<div class="wl"></div>' for _ in range(n))
C1 = card(1, 'Παρεμβάσεις κατά της εγκατάλειψης σε MOOC', 'Borrella, I., Caballero-Caballero, S., &amp; Ponce-Cueto, E. (2022). Taking action to reduce dropout in MOOCs: Tested interventions. <i>Computers &amp; Education, 179</i>, 104412. https://doi.org/10.1016/j.compedu.2021.104412', [
    ('Πλαίσιο', 'Μαζικά ανοικτά διαδικτυακά μαθήματα του προγράμματος MITx MicroMasters στη διαχείριση εφοδιαστικής αλυσίδας (ΗΠΑ).'), ('Ποιος', 'Η ομάδα των μαθημάτων, που θέλει να μειώσει την εγκατάλειψη.'),
    ('Τι έγινε', 'Τέσσερις παρεμβάσεις, ελεγμένες με δοκιμές A/B και φυσικά πειράματα. Οι μισές ήταν μηνύματα ηλεκτρονικού ταχυδρομείου προς εκπαιδευόμενους που ένα μοντέλο προέβλεπε ότι θα εγκαταλείψουν· οι άλλες άλλαζαν το ίδιο το περιεχόμενο, ώστε να γίνει προσιτότερο.'),
    ('Τι βρέθηκε', 'Τα μηνύματα δεν μείωσαν την εγκατάλειψη. Οι αλλαγές στο περιεχόμενο τη μείωσαν. Σε προηγούμενη εργασία των ίδιων (2019) το μοντέλο εντόπιζε το 80% όσων εγκατέλειπαν και τα μηνύματα ανοίγονταν, χωρίς αποτέλεσμα.'), ('Να προσέξετε', 'Εκπαιδευόμενοι MOOC, όχι φοιτητές πανεπιστημίου· ένα πρόγραμμα, ένας πάροχος.')])
C2 = card(2, 'Σύστημα έγκαιρης προειδοποίησης με παρέμβαση, σε διαδικτυακό πανεπιστήμιο', 'Bañeres, D., Rodríguez-González, M. E., Guerrero-Roldán, A.-E., &amp; Cortadas, P. (2023). An early warning system to identify and intervene online dropout learners. <i>International Journal of Educational Technology in Higher Education, 20</i>(1), 3. https://doi.org/10.1186/s41239-022-00371-5', [
    ('Πλαίσιο', 'Πρωτοετές, πλήρως διαδικτυακό μάθημα στο Ανοικτό Πανεπιστήμιο της Καταλονίας (UOC), Ισπανία.'), ('Ποιος', 'Διδάσκοντες και φοιτητές· 581 συμμετέχοντες από τους 957 εγγεγραμμένους.'),
    ('Τι έγινε', 'Το σύστημα εκτιμά καθημερινά ποιος κινδυνεύει να εγκαταλείψει (διακρίνει τον κίνδυνο εγκατάλειψης από τον κίνδυνο αποτυχίας) και στέλνει μηνύματα καθορισμού στόχου για τη συγκεκριμένη αξιολογούμενη δραστηριότητα που βρίσκεται σε εξέλιξη.'),
    ('Τι βρέθηκε', 'Η εγκατάλειψη μειώθηκε σημαντικά και η εμπλοκή με το μάθημα αυξήθηκε.'), ('Να προσέξετε', 'Ένα μάθημα, ένα ίδρυμα· η συμμετοχή ήταν εθελοντική (581 από 957).')])
C3 = card(3, 'Πίνακας πληροφοριών με πρόβλεψη, σε μάθημα προγραμματισμού', 'Hellings, J., &amp; Haelermans, C. (2022). The effect of providing learning analytics on student behaviour and performance in programming: A randomised controlled experiment. <i>Higher Education, 83</i>(1), 1–18. https://doi.org/10.1007/s10734-020-00560-z', [
    ('Πλαίσιο', 'Πρωτοετές μάθημα προγραμματισμού σε Java, σε πανεπιστήμιο εφαρμοσμένων επιστημών της Ολλανδίας.'), ('Ποιος', '556 φοιτητές: 276 στην ομάδα παρέμβασης, 280 στην ομάδα ελέγχου (τυχαιοποιημένο πείραμα).'),
    ('Τι έγινε', 'Επί οκτώ εβδομάδες η ομάδα παρέμβασης λάμβανε εβδομαδιαίο μήνυμα και είχε πρόσβαση σε πίνακα πληροφοριών με την πρόοδό της και την προβλεπόμενη πιθανότητα επιτυχίας.'),
    ('Τι βρέθηκε', 'Αυξήθηκε η διαδικτυακή δραστηριότητα των φοιτητών. Η επίδοση στην τελική εξέταση δεν άλλαξε. Η επίδραση διέφερε ανά ειδίκευση.'), ('Να προσέξετε', 'Ένα μάθημα, ένα ίδρυμα· η έκβαση είναι η επίδοση, όχι η εγκατάλειψη.')])
